import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { dirname } from "node:path";
import { randomBytes } from "node:crypto";

// A tiny JSON-file-backed store. Every change rewrites the whole file,
// via a temp file + rename so a crash mid-write can't corrupt it.
export function createStore(file) {
  let books = null;
  let writing = Promise.resolve();

  async function load() {
    if (books) return books;
    try {
      books = JSON.parse(await readFile(file, "utf8"));
      if (!Array.isArray(books)) throw new Error(`${file} does not contain a list of books`);
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      books = [];
    }
    return books;
  }

  function save() {
    const snapshot = JSON.stringify(books, null, 2) + "\n";
    writing = writing.then(async () => {
      await mkdir(dirname(file), { recursive: true });
      const tmp = `${file}.${process.pid}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, file);
    });
    return writing;
  }

  return {
    async list() {
      return [...(await load())];
    },
    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },
    async add({ title, author, notes }) {
      await load();
      const book = {
        id: randomBytes(6).toString("base64url"),
        title,
        author,
        notes: notes ?? "",
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },
    async update(id, changes) {
      const book = await this.get(id);
      if (!book) return null;
      Object.assign(book, changes);
      await save();
      return book;
    },
    async finish(id) {
      return this.update(id, { status: "finished", finishedAt: new Date().toISOString() });
    },
  };
}

