      await rename(tmp, file);
    });
    return writing;
  }

  return {
    async list() {
      return [...(await load())];
    },
    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },
    async add({ title, author, notes }) {
      await load();
      const book = {
        id: randomBytes(6).toString("base64url"),
        title,
        author,
        notes: notes ?? "",
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },
    async update(id, changes) {
      const book = await this.get(id);
      if (!book) return null;
      Object.assign(book, changes);
      await save();
      return book;
    },
    async finish(id) {
      return this.update(id, { status: "finished", finishedAt: new Date().toISOString() });
    },
  };
}

const esc = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

const date = (iso) => (iso ? new Date(iso).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric" }) : "");

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #1a5fb4; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding: 0; list-style: none; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #777; }
  .empty { color: #777; font-style: italic; }
  form.add { display: grid; gap: .5rem; }
  input, textarea, button { font: inherit; padding: .4rem; }
  textarea { min-height: 6rem; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: 1rem; border-radius: 4px; }
  .error { color: #b00; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function finishButton(book) {
  return `<form method="post" action="/books/${esc(book.id)}/finish"><button>Mark finished</button></form>`;
}

function bookList(books, empty, withFinish) {
  if (!books.length) return `<p class="empty">${empty}</p>`;
  return `<ul>${books
    .map(
      (b) => `<li><span><a href="/books/${esc(b.id)}">${esc(b.title)}</a> <span class="muted">by ${esc(b.author)}</span>${
        b.finishedAt ? ` <span class="muted">· ${date(b.finishedAt)}</span>` : ""
      }</span>${withFinish ? finishButton(b) : ""}</li>`,
    )
    .join("")}</ul>`;
}

function homePage(books, { error, values = {} } = {}) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
  return page(
    "My books",
    `<h2>Currently reading</h2>
${bookList(reading, "Nothing on the go.", true)}
<h2>Finished</h2>
${bookList(finished, "Nothing finished yet.", false)}
<h2>Add a book</h2>
${error ? `<p class="error">${esc(error)}</p>` : ""}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required value="${esc(values.title ?? "")}"></label>
  <label>Author <input name="author" required value="${esc(values.author ?? "")}"></label>
  <label>Notes <textarea name="notes">${esc(values.notes ?? "")}</textarea></label>
  <button>Add book</button>
</form>`,
  );
}

function bookPage(book) {
  const status =
    book.status === "finished"
      ? `Finished ${date(book.finishedAt)}`
      : `Reading since ${date(book.addedAt)}`;
  return page(
    `${book.title} by ${book.author}`,
    `<h2>${esc(book.title)}</h2>
<p>by ${esc(book.author)}</p>
<p class="muted">${status}</p>
<h3>Notes</h3>
${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : `<p class="empty">No notes.</p>`}
${book.status === "reading" ? finishButton(book) : ""}
<p><a href="/">← All books</a></p>`,
  );
}

async function readForm(req) {
  let body = "";
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 100_000) throw Object.assign(new Error("Form too large"), { status: 413 });
  }
  return Object.fromEntries(new URLSearchParams(body));
}

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

const notFound = (res) => send(res, 404, page("Not found", `<p>That book doesn't exist.</p><p><a href="/">← All books</a></p>`));

export function createApp(store) {
  return async function handle(req, res) {
    try {
      const { pathname } = new URL(req.url, "http://localhost");
      const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
      const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);

      if (req.method === "GET" && pathname === "/") {
        return send(res, 200, homePage(await store.list()));
      }

      if (req.method === "POST" && pathname === "/books") {
        const form = await readForm(req);
        const title = (form.title ?? "").trim();
        const author = (form.author ?? "").trim();
        const notes = (form.notes ?? "").trim();
        if (!title || !author) {
          return send(res, 400, homePage(await store.list(), { error: "Title and author are required.", values: form }));
        }
        const book = await store.add({ title, author, notes });
        return redirect(res, `/books/${book.id}`);
      }

      if (req.method === "GET" && bookMatch) {
        const book = await store.get(bookMatch[1]);
        return book ? send(res, 200, bookPage(book)) : notFound(res);
      }

      if (req.method === "POST" && finishMatch) {
        const book = await store.get(finishMatch[1]);
        if (!book) return notFound(res);
        if (book.status !== "finished") await store.finish(book.id);
        return redirect(res, "/");
      }

      return send(res, 404, page("Not found", `<p>Page not found.</p><p><a href="/">← All books</a></p>`));
    } catch (err) {
      console.error(err);
      send(res, err.status ?? 500, page("Error", `<p>Something went wrong.</p>`));
    }
  };
}

import { createServer } from "node:http";
import { createStore } from "./src/store.js";
import { createApp } from "./src/app.js";

const file = process.env.BOOKS_FILE ?? "data/books.json";
const port = Number(process.env.PORT ?? 3000);
const host = process.env.HOST ?? "127.0.0.1";

createServer(createApp(createStore(file))).listen(port, host, () => {
  console.log(`Books app on http://${host}:${port} (saving to ${file})`);
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { createServer } from "node:http";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createStore } from "../src/store.js";
import { createApp } from "../src/app.js";

let dir, file, server, base;

async function start() {
  server = createServer(createApp(createStore(file)));
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${server.address().port}`;
}
const stop = () => new Promise((r) => server.close(r));

const post = (path, fields) =>
  fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(fields),
    redirect: "manual",
  });

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  file = join(dir, "books.json");
  await start();
});
afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("books app", () => {
  it("shows empty sections on first run", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Nothing on the go.");
    expect(html).toContain("Nothing finished yet.");
  });

  it("adds a book, links to it, finishes it, and persists across restart", async () => {
    const res = await post("/books", { title: "Dune", author: "Frank Herbert", notes: "Spice <must> flow" });
    expect(res.status).toBe(303);
    const link = res.headers.get("location");
    expect(link).toMatch(/^\/books\/[\w-]+$/);

    const detail = await (await fetch(base + link)).text();
    expect(detail).toContain("Dune");
    expect(detail).toContain("Frank Herbert");
    expect(detail).toContain("Spice &lt;must&gt; flow");

    let home = await (await fetch(base + "/")).text();
    expect(home.indexOf("Dune")).toBeLessThan(home.indexOf("<h2>Finished"));

    expect((await post(link + "/finish", {})).status).toBe(303);
    home = await (await fetch(base + "/")).text();
    expect(home.indexOf("Dune")).toBeGreaterThan(home.indexOf("<h2>Finished"));

    const saved = JSON.parse(await readFile(file, "utf8"));
    expect(saved).toHaveLength(1);
    expect(saved[0].status).toBe("finished");

    await stop();
    await start();
    const again = await (await fetch(base + link)).text();
    expect(again).toContain("Dune");
    expect(again).toContain("Finished");
  });

  it("rejects a book without title or author", async () => {
    const res = await post("/books", { title: "", author: "Someone" });
    expect(res.status).toBe(400);
    expect(await res.text()).toContain("Title and author are required.");
  });

  it("404s for unknown books", async () => {
    expect((await fetch(base + "/books/nope")).status).toBe(404);
    expect((await post("/books/nope/finish", {})).status).toBe(404);
  });
});

